        max-width: 640px;
        margin: 16px 0 0;
        color: var(--muted);
        font-size: 1.05rem;
      }

      form {
        padding: 34px 44px 44px;
      }

      .form-field {
        padding: 26px;
        border: 1px solid var(--border);
        border-radius: 22px;
        background: var(--card);
      }

      .form-field + .form-field {
        margin-top: 20px;
      }

      .question-header {
        display: flex;
        align-items: flex-start;
        justify-content: space-between;
        gap: 18px;
        margin-bottom: 16px;
      }

      .question-title {
        margin: 0;
        font-size: 1.15rem;
        letter-spacing: -0.02em;
      }

      .question-number {
        flex: 0 0 auto;
        border-radius: 999px;
        background: #f2f4f7;
        color: var(--muted);
        font-size: 0.8rem;
        font-weight: 700;
        padding: 6px 10px;
      }

      .help-text {
        margin: -6px 0 18px;
        color: var(--muted);
        font-size: 0.95rem;
      }

      .choice-grid {
        display: grid;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 12px;
      }

      .choice {
        position: relative;
        display: flex;
        min-height: 58px;
        cursor: pointer;
        align-items: center;
        gap: 12px;
        border: 1px solid var(--border);
        border-radius: 16px;
        padding: 14px 16px;
        background: #fbfcff;
        font-weight: 650;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease,
          background-color 160ms ease;
      }

      .choice:hover {
        transform: translateY(-1px);
        border-color: #b8c2d8;
        box-shadow: 0 10px 22px rgba(15, 23, 42, 0.08);
      }

      .choice input {
        width: 20px;
        height: 20px;
        margin: 0;
        accent-color: var(--accent);
      }

      .choice:has(input:checked) {
        border-color: var(--accent);
        background: var(--accent-soft);
        box-shadow: 0 12px 28px rgba(79, 70, 229, 0.16);
      }

      .actions {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        margin-top: 28px;
      }

      .selection-note {
        margin: 0;
        color: var(--muted);
        font-size: 0.95rem;
      }

      button {
        cursor: pointer;
        border: 0;
        border-radius: 999px;
        background: var(--accent);
        color: #fff;
        font: inherit;
        font-weight: 800;
        padding: 14px 24px;
        box-shadow: 0 14px 30px rgba(79, 70, 229, 0.28);
        transition:
          background-color 160ms ease,
          transform 160ms ease,
          box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        background: var(--accent-dark);
        box-shadow: 0 18px 36px rgba(79, 70, 229, 0.34);
      }

      button:focus-visible,
      .choice:has(input:focus-visible) {
        outline: 3px solid rgba(79, 70, 229, 0.28);
        outline-offset: 3px;
      }

      @media (max-width: 680px) {
        .hero,
        form {
          padding-right: 22px;
          padding-left: 22px;
        }

        .choice-grid {
          grid-template-columns: 1fr;
        }

        .actions {
          align-items: stretch;
          flex-direction: column;
        }

        button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <main id="root"></main>

    <script>
      const quizQuestions = [
        {
          id: "language-types",
          title: "Which of these are programming languages?",
          helpText: "Select every option that is a general-purpose or domain-specific programming language.",
          choices: ["Python", "HTML", "JavaScript", "French"],
        },
        {
          id: "compiled-languages",
          title: "Which languages are commonly compiled before execution?",
          choices: ["C++", "Rust", "CSS", "Go"],
        },
        {
          id: "web-languages",
          title: "Which languages are commonly used to build web interfaces?",
          choices: ["JavaScript", "TypeScript", "SQL", "CSS"],
        },
      ];

      function Choice({ questionId, choice }) {
        const inputId = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${inputId}">
            <input id="${inputId}" name="${questionId}" type="checkbox" value="${choice}" />
            <span>${choice}</span>
          </label>
        `;
      }

      function QuizQuestion({ question, index }) {
        return `
          <div class="form-field">
            <div class="question-header">
              <h2 class="question-title">${question.title}</h2>
              <span class="question-number">Question ${index + 1}</span>
            </div>
            ${question.helpText ? `<p class="help-text">${question.helpText}</p>` : ""}
            <div class="choice-grid">
              ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
            </div>
          </div>
        `;
      }

      function QuizApp({ questions }) {
        return `
          <section class="page-shell">
            <article class="quiz-card">
              <header class="hero">
                <p class="eyebrow">Multi-select quiz</p>
                <h1>Computer Languages Check</h1>
                <p class="intro">
                  Test your language knowledge with three quick questions. More than one answer may be correct.
                </p>
              </header>

              <form id="quiz-form">
                ${questions.map((question, index) => QuizQuestion({ question, index })).join("")}
                <div class="actions">
                  <p class="selection-note">Choose all answers that apply for each question.</p>
                  <button type="submit">Submit answers</button>
                </div>
              </form>
            </article>
          </section>
        `;
      }

      document.querySelector("#root").innerHTML = QuizApp({ questions: quizQuestions });

      document.querySelector("#quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();
        alert("Thanks for submitting your quiz answers.");
      });
    </script>
  </body>
</html>
